pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20 mock that always returns true on transferFrom
        vm.prank(address(0xaBcD));
        MockToken token = new MockToken();
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);

        // Call transfer with from=0xaBcD, token address, one recipient, value=100
        bool ok;
        try c.transfer(address(0xaBcD), address(token), tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: transfer succeeds (ok==true). Modified: require(!_s) causes revert, so ok==false
        assertTrue(ok);
    }
}

