pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a token that reverts on transferFrom
        address token = address(new RevertingToken());
        address from = address(0x1234);
        address[] memory tos = new address[](1);
        tos[0] = address(0x5678);
        uint256 v = 100;
        // The reference version reverts because require(_s) fails
        bool ok;
        try c.transfer(from, token, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: reverts -> ok=false; Modified: ignores revert -> ok=true
        assertTrue(!ok);
    }
}

contract RevertingToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("transferFrom failed");
    }
}

