import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a non-existent address for caddress to cause the call to fail
        address badAddress = address(0x1234);
        address from = address(0x1);
        address[] memory tos = new address[](1);
        tos[0] = address(0x2);
        uint v = 100;

        // The reference requires the call to succeed; the modified version ignores the failure.
        // We test that the function returns true only when it is the reference (which reverts).
        // Since we expect the reference to fail, we catch the revert.
        bool success;
        try c.transfer(from, badAddress, tos, v) {
            success = true;
        } catch {
            success = false;
        }
        // The reference reverts -> success == false; modified returns true -> success == true.
        // So we assert false to catch the modified version: assertTrue(!success) holds for reference, fails for modified.
        assertTrue(!success);
    }
}

