pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like token that tracks totalSupply via transferFrom
        Token token = new Token();
        address from = address(0xabcd);
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint v = 100;

        // The reference: transfer calls token.transferFrom(from, tos[0], v)
        // which increases token.totalSupply by v (100).
        bool ok;
        try c.transfer(from, address(token), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
        // The reference: totalSupply becomes 100.
        // The buggy: totalSupply becomes 101 (v+1 = 101).
        assertEq(token.totalSupply(), 100);
    }
}

contract Token {
    uint256 public totalSupply;
    function transferFrom(address, address, uint256 amount) external returns (bool) {
        totalSupply += amount;
        return true;
    }
}

